export function reservation(state, actions) { const card=document.createElement('section'); const h=document.createElement('h2'); h.textContent=state.title||'Studio reservation';card.append(h);const status=document.createElement('p');status.setAttribute('role','status');status.textContent={loading:'Checking slots…',empty:'No slots available',failed:'Unable to reserve. Choose another time.',confirmed:'Reservation confirmed',denied:'Ask an owner for booking access'}[state.kind]||'Choose a time';card.append(status);const select=document.createElement('select');select.setAttribute('aria-label','Reservation time');for(const time of state.times||[])select.add(new Option(time,time));card.append(select);const b=document.createElement('button');b.textContent=state.kind==='loading'?'Checking…':'Reserve';b.disabled=['loading','empty','disabled','denied'].includes(state.kind);b.onclick=()=>actions.reserve(select.value);card.append(b);return card;}
export const productionActions={reserve:time=>fetch('https://reservations.example.invalid/create',{method:'POST',body:JSON.stringify({time})})};
